#!/usr/bin/env bash
# Two release lines decide from paths whether a commit releases: a commit since the line's newest
# tag that touches one of the paths its version step hands `release-push.sh version` releases, and
# any other commit releases nothing. Both lines ship Go binaries, so a file their build reads that
# those paths leave out changes what ships and releases nothing. This check holds the paths of
# both lines to what go says the builds read.
#
# THE LEGION LINE, release.yaml's legion_build: the paths after `--` in $LEGION_VERSION_ARGS,
# written by hand, and then $LEGION_GO_INPUTS. The binary compiles in packages of the envoy module
# too, and those were a list kept by hand that fell behind: main at 4055c4a523 named 14 of the 17
# packages/envoy packages `go list -deps ./cmd/legion` names, so a change to internal/ctxlock,
# internal/dispatch/bytelru or internal/fold changed the binary and released nothing.
# So $LEGION_GO_INPUTS is a generated block of release.yaml's workflow `env:`, from a
# `# BEGIN generated by ...` line to `# END generated`, holding every path go names for the
# binary (below) that no path of $LEGION_VERSION_ARGS covers, one a line, sorted.
#
# THE LEGION-ENVOY LINE, release-envoy-listener.yaml's release_build and release_publish: the
# paths after `--` in $LEGION_ENVOY_VERSION_ARGS, written by hand. They name packages/envoy/
# whole, so no block lists its packages; the check holds those paths to cover every path go
# names for the archives the workflow compiles on the runner, in packages/envoy under the root
# go.work. The image builds from packages/envoy's own module files, with no go.work, and its
# inputs are .github/scripts/check-image-trigger-paths.sh's to hold.
#
# Which programs, targets and cgo settings each line lists is .github/scripts/
# release_version_inputs.py's, the one plan this check runs and ci_job_reads.py turns into the
# ci-filters gate's go commands; its header says why each is there.
#
# What go names for a listing, on either line:
#   * the directory of every package of this repository it names. A directory stands for the
#     package's files, its embedded ones among them, since go:embed reads nothing outside it;
#   * the files that decide which version of each module the binary links: the workspace's go.work
#     and go.work.sum (`go env GOWORK`), and the go.mod and go.sum of every module `go list -m`
#     names there and of every module that provides one of those packages, each one that exists.
# A path covers itself and the tree under it, as a git pathspec does. An exclude, written
# `:(exclude)X` or `:!X`, drops what it matches from every release whatever else names it.
#
# Fails on:
#   1. a LEGION_GO_INPUTS block that is not exactly the one `write` writes, naming every path it
#      lacks and every path it names that go does not, or a release.yaml with no such block or
#      more than one;
#   2. a block that is not the LEGION_GO_INPUTS of release.yaml's workflow `env:`;
#   3. a job that hands a line's paths to release-push.sh - legion_build's version step, and
#      release-envoy-listener.yaml's release_build version step and release_publish confirm step,
#      release_version_inputs.py's VERSION_STEPS - that is not pinned, up to and including that
#      step, to what the module names. Shell is not read, since code can reach $GITHUB_ENV or
#      $GITHUB_PATH however it spells them or through a helper it calls; each piece is compared:
#      the step's run: character for character after YAML has read it (an escaped `\$`, a `${{ }}`
#      line, a comment or any added line is a difference), naming the first line that differs,
#      its env: key for key (a PATH there picks the bash release-push.sh's `#!/usr/bin/env bash`
#      runs), and its if: as the module names it, with no key but name and id free (an `if:
#      false`, a continue-on-error: or a timeout-minutes: can end it with its decision thrown
#      away); its job's version and skip outputs as the module names them, since the publish steps
#      read the decision there (a `skip: "true"` skips the release the step chose); every if: that
#      reads the decision - those outputs, the step's own, or an earlier reader step's outcome -
#      the one DECISION_READERS names, by the step's id:, name: or position, and no reader it does
#      not name (an `if: false` on a publish step skips the release as surely); every step
#      before it one of STEPS_BEFORE_VERSION_STEPS on every key but name, id, if, timeout-minutes
#      and continue-on-error; the workflow's env: a literal mapping of WORKFLOW_ENV_KEYS' variables
#      alone, so a BASH_ENV, PATH, LD_PRELOAD, GIT_DIR or GH_REPO is refused as one more unlisted
#      name; the job setting only the module's JOB_KEYS, so no services:, container:, env:,
#      defaults: or reusable workflow, on its runs-on: (a self-hosted runner runs its own hooks
#      first); the workflow with no defaults but `run: {shell: bash}`; and the step under `bash`
#      itself (`bash --rcfile x -i {0}` sources x first). An expression in place of any of those
#      mappings is refused, since no one can read what it sets. Whether a release workflow runs
#      at all - its on: triggers, a job's if:, concurrency: and timeout-minutes: where they do not
#      read the decision, the runner image behind the label - is outside this rule;
#   4. a path go names for the legion-envoy archives that no path of $LEGION_ENVOY_VERSION_ARGS
#      covers, naming it and the listing that names it;
#   5. an exclude of either line's paths that drops a path go names for it, or that drops anything
#      inside a package directory go names (a file of the package, an embedded file among them);
#      an exclude spelled any way but `:(exclude)X` and `:!X` (`:^X` among them), or whose X is
#      not canonical - a relative path with no `./`, no leading `/`, no `//` and no `..`, which git
#      reads as the same path while a compare of paths as written does not - naming the canonical
#      spelling; an exclude holding a wildcard, which git matches by its own glob rules and this
#      check does not; a value holding a `${{ }}` expression, which GitHub renders into the paths
#      first; or a path written with any other pathspec magic, which this check cannot read;
#   6. a go command that fails, a package of this repository that go list cannot load, or a
#      listing that does not name the program it lists, since what that program links is then
#      unknown and a listing of nothing would pass everything.
#
# The go commands run through .github/scripts/go_offline.py, as check-ci-filters.sh's do, and that
# module says why: with GOPROXY=off over an empty module cache, and GONOPROXY=none and GOENV=off so
# no setting of the machine reaches past that, nothing is downloaded and a cold runner gives the
# answer a warm machine does. A third-party package then fails to load,
# which loses no package of this repository, since no module outside it imports one. The
# toolchain each module pins is resolved first, under this machine's own cache and proxy, and its
# own binary runs every go command under GOTOOLCHAIN=local.
#
# THE TWO MODES. `check`, the default a bare call takes, is every refusal above. `write` rewrites
# the block in release.yaml instead of refusing rule 1, and refuses everything else as `check`
# does; it writes nothing when rule 5 or 6 refuses for the legion line, since the block would then
# be computed from a set that is unknown. It writes only inside the block. Any other word, or more
# than one, fails.
#
# Run from anywhere: .github/scripts/check-legion-version-inputs.sh
#                    .github/scripts/check-legion-version-inputs.sh write
# CI runs it in ci.yaml's ci-filters job, and its tests in ci.yaml's test job.
set -euo pipefail

cd "$(dirname "$0")/../.."

# A bare call checks: a caller who says nothing is asking for the verdict, never for a rewrite of
# release.yaml.
case "$#:${1:-}" in
  0: | 1:check | 1:write) ;;
  *)
    echo "::error file=.github/scripts/check-legion-version-inputs.sh::this check takes one optional mode: \`check\` (the default) refuses a LEGION_GO_INPUTS block of release.yaml that is not what go names, and \`write\` writes that block instead. Run \`.github/scripts/check-legion-version-inputs.sh\` or \`.github/scripts/check-legion-version-inputs.sh write\`." >&2
    exit 1
    ;;
esac

# go_offline.py and release_version_inputs.py sit beside this script in the repository it checks.
# PYTHONDONTWRITEBYTECODE keeps the imports from leaving a __pycache__ in the tree.
PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=.github/scripts exec python3 - "${1:-check}" <<'PY'
import itertools
import json
import posixpath
import re
import shutil
import sys
import tempfile
from pathlib import Path

import yaml

import go_offline
import release_version_inputs as plan
from go_offline import decode_stream

MODE = sys.argv[1]
SELF = ".github/scripts/check-legion-version-inputs.sh"
PLAN = ".github/scripts/release_version_inputs.py"
RELEASE = plan.RELEASE
LISTENER = plan.LISTENER
TARGETS = ".github/go-release-targets.json"
CLIENT_TARGETS = ".github/agent-secrets-client-targets.json"
DAEMON = plan.DAEMON
ENVOY = plan.ENVOY
HAND = plan.LEGION_ARGS
ENVOY_ARGS = plan.ENVOY_ARGS
BLOCK = plan.LEGION_BLOCK
# The keys of a step this check leaves free: they name a step, gate it or bound its time, and run
# no code. Every other key of a step up to a checked version step is pinned (uses:, with:, run:,
# env:, shell:, working-directory:, and any key GitHub adds).
FREE_STEP_KEYS = ("name", "id", "if", "timeout-minutes", "continue-on-error")
BEGIN = f"  # BEGIN generated by `{SELF} write`"
END = "  # END generated"
HEAD = [
    f"{BEGIN}: what go",
    f"  # decides the binary from beyond ${HAND}'s paths, one path a line. An edit by",
    "  # hand is refused: that check, which the ci-filters job runs, names what go adds or drops.",
]
# The two spellings of git's exclude magic this check reads: the long form and the one short form.
EXCLUDE_FORMS = (":(exclude)", ":!")
# One component of a canonical path: what this repository's paths are spelled with.
COMPONENT = re.compile(r"[A-Za-z0-9._+@-]+")
# What git reads as a glob in a pathspec (its wildmatch: `*`, `?`, a `[` class, a `\` escape).
WILDCARD = re.compile(r"[*?\[\\]")
REPO = Path.cwd().resolve()
problems = []


def annotation(path, message, line=None):
    where = f"file={path}" + (f",line={line}" if line else "")
    return f"::error {where}::{message}"


def problem(message, path, line=None):
    problems.append(annotation(path, message, line))


def fatal(message, path):
    """Stop on `message`, printing the problems found before it too, so none is lost."""
    print("\n".join([*problems, annotation(path, message)]), file=sys.stderr)
    raise SystemExit(1)


def report_and_stop_on_problems():
    if problems:
        print("\n".join(problems), file=sys.stderr)
        raise SystemExit(1)


def read(path):
    try:
        return Path(path).read_text(encoding="utf-8")
    except FileNotFoundError:
        fatal(f"{path} is missing", path)
    except UnicodeDecodeError as error:
        fatal(f"{path} is not readable as text: {error.reason}", path)


def load(path, text):
    try:
        return yaml.safe_load(text)
    except yaml.YAMLError as error:
        fatal(f"{path} is not YAML this check can read: {' '.join(str(error).split())}", path)


def rel(path):
    return go_offline.relative(path, REPO)


def covers(spec, path):
    """Whether the plain pathspec `spec` matches `path`, a file or a directory written with its /."""
    spec, path = spec.rstrip("/"), path.rstrip("/")
    return path == spec or path.startswith(spec + "/")


def env_of(path, doc):
    env = doc.get("env") if isinstance(doc, dict) else None
    return env if isinstance(env, dict) else {}


def canonical(payload):
    """Whether `payload` is a path as this check compares paths: relative to the repository's root,
    components of COMPONENT that are not `.` or `..`, single slashes, at most one trailing one. A
    `./`, a leading `/` or a `//` is a path git reads as the same one and a string compare does not."""
    parts = payload.removesuffix("/").split("/")
    return bool(payload) and all(COMPONENT.fullmatch(part) and part not in (".", "..") for part in parts)


def spelling(payload):
    """The canonical spelling of `payload`, where there is one."""
    norm = posixpath.normpath(payload.lstrip("/")) if payload.strip("/") else ""
    return norm if canonical(norm) else None


def pathspecs(path, doc, key):
    """The paths after `--` in the workflow env's `key`: the plain ones, and each exclude as
    (its text, the path it drops). Rule 5's refusals: a value holding a `${{ }}` expression; an
    exclude in any spelling but `:(exclude)` and `:!`, one holding a wildcard, and one whose path is
    not canonical; and any other magic."""
    value = env_of(path, doc).get(key)
    if not isinstance(value, str):
        fatal(f"{path}'s workflow env: holds no {key} string", path)
    if "${{" in value:
        problem(f"{key} holds a `${{{{ }}}}` expression, which GitHub renders into the paths before the step reads "
                f"them and this check does not; write the paths themselves", path)
    words = value.split()
    if "--" not in words:
        fatal(f"{path}'s {key} has no `--`, after which release-push.sh version reads its paths", path)
    plain, excludes = [], []
    for word in words[words.index("--") + 1:]:
        if not word.startswith(":"):
            plain.append(word)
            continue
        form = next((form for form in EXCLUDE_FORMS if word.startswith(form)), None)
        payload = word[len(form):] if form else word[2:]
        fixed = spelling(payload)
        either = f"`:(exclude){fixed}` or `:!{fixed}`" if fixed else "`:(exclude)<path>` or `:!<path>`"
        if form is None and word.startswith(":^"):
            problem(f"{key} names `{word}`, git's `:^` spelling of an exclude, which this check reads in two "
                    f"spellings alone; write it {either}", path)
        elif form is None:
            problem(f"{key} names `{word}`, a pathspec with magic this check cannot read: it reads "
                    f"plain paths and excludes alone, and cannot say what this one leaves out", path)
        elif WILDCARD.search(payload):
            problem(f"{key} names `{word}`, an exclude with a wildcard, which git matches by its own glob "
                    f"rules and this check does not: it cannot say which path the exclude drops; name the "
                    f"paths it means instead", path)
        elif not canonical(payload):
            problem(f"{key} names `{word}`, an exclude whose path is not canonical: git reads a `./`, a leading "
                    f"`/`, a `//` or a `..` as another spelling of a path, and this check compares paths as "
                    f"written; write it {f'`{form}{fixed}`' if fixed else either}", path)
        else:
            excludes.append((word, payload))
    return plain, excludes


def targets(path, key, pairs):
    """The list `key` of the target file `path`: os/arch pairs, or bare arches."""
    try:
        listed = json.loads(read(path))[key]
    except (ValueError, KeyError, TypeError):
        listed = None
    if not isinstance(listed, list) or not listed or not all(
            isinstance(t, str) and t.count("/") == (1 if pairs else 0) for t in listed):
        fatal(f"{path} holds no `{key}` list of {'os/arch targets' if pairs else 'arches'}", path)
    return listed


class Go:
    """The go commands of one module directory, under the toolchain that directory pins."""

    def __init__(self, workdir, modcache):
        self.workdir, self.modcache = workdir, modcache
        try:
            self.binary, stderr = go_offline.toolchain(workdir)
        except FileNotFoundError:
            fatal(f"no go on PATH, so what {workdir}'s programs link is unknown", SELF)
        if not self.binary:
            fatal(f"`go env GOROOT` in {workdir} names no toolchain ({' '.join(stderr.split())[:500]}), "
                  f"so what its programs link is unknown", SELF)

    def __call__(self, args, **extra):
        result = go_offline.run(self.binary, args, self.workdir, self.modcache, extra)
        if result.returncode != 0:
            fatal(f"in {self.workdir}, go {' '.join(args)} failed, so what it lists is unknown: "
                  f"{' '.join(result.stderr.split())[:500]}", SELF)
        return result.stdout


def named(go, listings):
    """Every path go names for `listings` (release_version_inputs.Listing records, each of go's
    own module directory) mapped to the label of the first listing that names it: package
    directories with their /, and module files."""
    modules = [line.split("\t") for line in go(["list", "-m", "-f", "{{.Path}}\t{{.GoMod}}"]).splitlines() if line]
    first_party = [module for module, _ in modules]
    paths, gomods = {}, {gomod: f"go list -m in {go.workdir}" for _, gomod in modules if gomod}
    gowork = go(["env", "GOWORK"]).strip()
    files = {gowork: f"go env GOWORK in {go.workdir}", gowork + ".sum": f"go env GOWORK in {go.workdir}"} \
        if gowork and gowork != "off" else {}
    for record in listings:
        packages, env, label = record.packages, record.env, record.label
        if record.workdir != go.workdir:
            fatal(f"the listing {label} runs in {record.workdir}, not in {go.workdir}", SELF)
        listing = decode_stream(go(["list", "-e", "-deps", "-json=ImportPath,Dir,Module,Error", *packages], **env))
        dirs = {Path(pkg["Dir"]).resolve() for pkg in listing if pkg.get("Dir")}
        for package in packages:
            if (REPO / go.workdir / package).resolve() not in dirs:
                fatal(f"go list -deps {package} in {go.workdir} for {label} named no package in its directory, "
                      f"so what it links is unknown", SELF)
        for pkg in listing:
            name = pkg.get("ImportPath", "")
            directory = rel(pkg["Dir"]) if pkg.get("Dir") else None
            ours = directory is not None or any(name == m or name.startswith(m + "/") for m in first_party)
            if ours and pkg.get("Error"):
                problem(f"go list cannot load {name} for {label}, so what it links is unknown: "
                        f"{' '.join(str(pkg['Error'].get('Err', '')).split())[:500]}", SELF)
            if directory is None:
                continue
            paths.setdefault(directory + "/", label)
            if (pkg.get("Module") or {}).get("GoMod"):
                gomods.setdefault(pkg["Module"]["GoMod"], label)
    for gomod, label in gomods.items():
        files.setdefault(gomod, label)
        files.setdefault(str(Path(gomod).parent / "go.sum"), label)
    for path, label in files.items():
        if Path(path).is_file() and rel(path):
            paths.setdefault(rel(path), label)
    return paths


def refuse_excluded(path, key, excludes, found):
    """Rule 5: an exclude that drops a path go names, or that drops something inside a package
    directory go names, one of that package's files or its embedded ones among them."""
    for path_named, label in sorted(found.items()):
        for spec, dropped in excludes:
            if covers(dropped, path_named):
                problem(f"{key}'s `{spec}` drops {path_named}, which go names for {label}, from every release "
                        f"whatever else names it; narrow the exclude", path)
            elif path_named.endswith("/") and covers(path_named, dropped):
                problem(f"{key}'s `{spec}` drops {dropped.rstrip('/')}, inside {path_named}, a package directory "
                        f"go names for {label}, from every release whatever else names it; a change there can "
                        f"change the binary, so drop the exclude", path)


def shown(line):
    return f"`{line}`" if line else "nothing"


def rendered(value):
    """A step's value as a message shows it: an expression or text as written, a mapping compact."""
    if value is None:
        return "nothing"
    text = value if isinstance(value, str) else json.dumps(value, sort_keys=True)
    text = " ".join(text.split())
    return f"`{text[:200]}{'…' if len(text) > 200 else ''}`"


def text_difference(have, want):
    """Where the text `have` first differs from `want`: its line number, and each one's line there."""
    have, want = have.split("\n"), want.split("\n")
    n = next((i for i, (a, b) in enumerate(zip(have, want)) if a != b), min(len(have), len(want)))
    return n + 1, have[n] if n < len(have) else "", want[n] if n < len(want) else ""


def pinned(step):
    return {key: value for key, value in step.items() if key not in FREE_STEP_KEYS}


def approved(spec):
    return {key: value for key, value in (("uses", spec.uses), ("with", spec.with_), ("run", spec.run),
                                         ("env", spec.env)) if value is not None}


def differences(have, want, name):
    """What a step's pinned keys `have` hold where the listed step `name`'s `want` hold otherwise."""
    return "; ".join(f"its {key}: is {rendered(have.get(key))} where `{name}`'s is {rendered(want.get(key))}"
                     for key in sorted(set(have) | set(want)) if have.get(key) != want.get(key))


def earlier_step(path, spec, where, n, step):
    """Rule 3 for a step before a checked version step: it is one of STEPS_BEFORE_VERSION_STEPS on
    every key but FREE_STEP_KEYS."""
    label = f"step {n + 1} of {spec.job}"
    if isinstance(step, dict) and isinstance(step.get("name"), str):
        label += f" (`{step['name']}`)"
    rule = (f"{label}, before {where}, is not one of {PLAN}'s STEPS_BEFORE_VERSION_STEPS: before a checked version "
            f"step only those run, each exactly as listed on every key but {', '.join(FREE_STEP_KEYS)}, since any "
            f"other code can write $GITHUB_ENV or $GITHUB_PATH for the step however it spells them, or through a "
            f"helper it calls")
    if not isinstance(step, dict):
        problem(f"{rule}; it is no mapping", path)
        return
    have = pinned(step)
    listed = plan.STEPS_BEFORE_VERSION_STEPS
    if any(have == approved(spec_) for spec_ in listed):
        return
    alike = [s for s in listed if (s.uses is not None and s.uses == have.get("uses"))
             or (s.run is not None and s.run == have.get("run"))]
    if alike:
        best = min(alike, key=lambda s: sum(have.get(k) != v for k, v in approved(s).items()) + len(set(have) - set(approved(s))))
        detail = differences(have, approved(best), best.name)
    elif "uses" in have:
        detail = f"it runs the action {rendered(have['uses'])}, which no listed step runs"
    elif isinstance(have.get("run"), str):
        detail = f"its run: is no listed command (its line 1 is {shown(have['run'].split(chr(10))[0])})"
    else:
        detail = f"it runs neither a listed action nor a listed command ({rendered(have)})"
    problem(f"{rule}; {detail}", path)


def defaults_problem(scope, defaults, where, path):
    """A workflow defaults: other than none or `run: {shell: bash}` reaches the step: a
    working-directory: runs its relative .github/scripts/release-push.sh from another tree."""
    if defaults is None:
        return
    run = defaults.get("run") if isinstance(defaults, dict) else None
    if not isinstance(defaults, dict) or set(defaults) - {"run"} or not isinstance(run, dict) or set(run) - {"shell"}:
        problem(f"{scope} defaults: is {rendered(defaults)}, which reaches {where}: a workflow holding a checked "
                f"version step sets no defaults but `run: {{shell: bash}}`, since a working-directory: runs the "
                f"step's relative release-push.sh from another tree", path)


def default_shell(defaults):
    """The run.shell of a defaults:, or None where it has none or is no mapping (defaults_problem
    refuses that shape)."""
    run = defaults.get("run") if isinstance(defaults, dict) else None
    return run.get("shell") if isinstance(run, dict) else None


def version_step(doc, spec):
    """Rule 3 for one of release_version_inputs.py's VERSION_STEPS: its job is pinned up to and
    including the step. The job sets only JOB_KEYS and runs on the module's runner; every step
    before the step is one of STEPS_BEFORE_VERSION_STEPS; and the step's run: and env: are the
    module's, it sets no other pinned key, and it runs under `bash` itself."""
    path = spec.workflow
    jobs = doc.get("jobs") if isinstance(doc, dict) else None
    job = (jobs or {}).get(spec.job)
    where = f"{spec.job}'s step `{spec.step_id}`"
    if not isinstance(job, dict):
        problem(f"{path} must hold the job {spec.job}, with {where}; it holds none", path)
        return
    for key in sorted(set(job) - set(plan.JOB_KEYS)):
        problem(f"{spec.job} sets {key}: ({rendered(job[key])}), which {PLAN}'s JOB_KEYS does not list: a job holding "
                f"a checked version step sets only the keys those jobs use today, since another (services:, "
                f"container:, env:, defaults:, a reusable workflow's uses:, …) can run code or set the environment "
                f"before {where}, none of which this check reads", path)
    if job.get("runs-on") != spec.runs_on:
        problem(f"{spec.job}'s runs-on: is {rendered(job.get('runs-on'))}, where {PLAN} names `{spec.runs_on}` for it: "
                f"another runner, a self-hosted one above all, can run its own hooks and set its own environment "
                f"before {where}, none of which this check reads", path)
    outputs = job.get("outputs")
    if spec.outputs is not None and not isinstance(outputs, dict):
        problem(f"{spec.job}'s outputs: is {rendered(outputs)}, not a literal mapping holding {', '.join(spec.outputs)} as "
                f"{PLAN} names them, so no one can read what it hands on of {where}'s decision", path)
    for key, want in (spec.outputs or {}).items() if isinstance(outputs, dict) else ():
        if outputs.get(key) != want:
            problem(f"{spec.job}'s output {key} is {rendered(outputs.get(key))}, where {PLAN} names `{want}` for it: the "
                    f"publish steps read needs.{spec.job}.outputs.{key} as {where}'s decision, so another value throws "
                    f"that decision away (a `skip: \"true\"` skips the release the step chose)", path)
    steps = job.get("steps") if isinstance(job.get("steps"), list) else []
    found = [i for i, step in enumerate(steps) if isinstance(step, dict) and step.get("id") == spec.step_id]
    if len(found) != 1 or not isinstance(steps[found[0]].get("run"), str):
        problem(f"{path} must hold one {where} with a run:, the one {PLAN} names for it; it holds {len(found)}", path)
        return
    for n, earlier in enumerate(steps[:found[0]]):
        earlier_step(path, spec, where, n, earlier)
    step = steps[found[0]]
    if step["run"] != spec.run:
        n, got, need = text_difference(step["run"], spec.run)
        problem(f"{where}'s run: must be, character for character, the one {PLAN} names for it, since shell that "
                f"reads like the command can keep the paths from release-push.sh: its line {n} is {shown(got)} "
                f"where that one's is {shown(need)}", path)
    env = step.get("env")
    if env != spec.env:
        if env is not None and not isinstance(env, dict):
            detail = f"it is {rendered(env)}, an expression, not a literal mapping, so no one can read what it sets"
        else:
            have, want = env or {}, spec.env or {}
            detail = "; ".join([*(f"it sets {key}, which that one does not" for key in sorted(set(have) - set(want))),
                                *(f"it lacks {key}" for key in sorted(set(want) - set(have))),
                                *(f"its {key} is {rendered(have[key])} where that one's is {rendered(want[key])}"
                                  for key in sorted(set(have) & set(want)) if have[key] != want[key])])
        problem(f"{where}'s env: must be, key for key, the one {PLAN} names for it ({rendered(spec.env)}), since a "
                f"variable there can change what the command hands release-push.sh or what that script reads "
                f"(PATH picks the bash its `#!/usr/bin/env bash` runs): {detail}", path)
    if step.get("if") != spec.if_:
        problem(f"{where}'s if: is {rendered(step.get('if'))}, where {PLAN} names {rendered(spec.if_)} for it: an if: "
                f"that skips the step throws its decision away, and a skipped step hands on no version and no skip",
                path)
    # The step's free keys are its name: and id: alone. A continue-on-error: or timeout-minutes: can
    # end it with its outputs empty and the job still green: the confirm step's empty `release` then
    # skips every release step after it with no failure anywhere.
    for key in sorted(set(step) - {"name", "id", "run", "env", "shell", "if"}):
        problem(f"{where} sets {key}: ({rendered(step[key])}), which a checked version step does not", path)
    for scope, shell in (("its own", step.get("shell")), ("the workflow's defaults.run", default_shell(doc.get("defaults")))):
        if shell is not None and shell != "bash":
            problem(f"{scope} shell: is `{shell}`, where {where} must run under `bash` itself: any other shell line "
                    f"runs other code first or reads the run: another way (`bash --rcfile x -i {{0}}` sources x)", path)


# A selector names what holds an if: in a job, as a Reader does: ("job",) for the job's own if:,
# else ("id", id), ("name", name) or ("position", n), by id: first, then name:, then position.
def reader_selector(reader):
    if reader.position == 0:
        return ("job",)
    if reader.id is not None:
        return ("id", reader.id)
    if reader.name is not None:
        return ("name", reader.name)
    return ("position", reader.position)


def step_selector(step, n):
    if isinstance(step.get("id"), str):
        return ("id", step["id"])
    if isinstance(step.get("name"), str):
        return ("name", step["name"])
    return ("position", n)


def described(selector):
    """A selector as a message names it."""
    kind = selector[0]
    if kind == "job":
        return "the job's own if:"
    if kind == "id":
        return f"the step with id {selector[1]}"
    if kind == "name":
        return f"the step `{selector[1]}`"
    return f"step {selector[1]}"


def decision_readers(path, doc):
    """Rule 3's readers for the workflow `path`: an if: that reads a checked version step's decision
    - its job's version or skip output through needs.<job>.outputs anywhere in the workflow, the
    step's own outputs within its job, or the outcome or outputs of an earlier step of the same job
    that is itself such a reader - is the one DECISION_READERS names for it, and each reader
    DECISION_READERS names holds that if:."""
    jobs = doc.get("jobs") if isinstance(doc, dict) else None
    jobs = jobs if isinstance(jobs, dict) else {}
    specs = [spec for spec in plan.VERSION_STEPS if spec.workflow == path]
    anywhere = [re.compile(rf"\bneeds\.{re.escape(s.job)}\.outputs\.(?:{'|'.join(map(re.escape, s.outputs))})\b")
                for s in specs if s.outputs]
    held = {}   # (job, selector) -> the if: it holds, for the job itself and each of its steps
    index = {}  # (job, selector) -> the step's 1-based place in its job, 0 for the job itself
    found = {}  # (job, selector) -> the if: of each reader the traversal finds
    for job_name, job in jobs.items():
        if not isinstance(job, dict):
            continue
        own = [re.compile(rf"\bsteps\.{re.escape(s.step_id)}\.outputs\.") for s in specs if s.job == job_name]
        checked = {s.step_id for s in specs if s.job == job_name}
        cond = job.get("if")
        held[(job_name, ("job",))] = cond
        index[(job_name, ("job",))] = 0
        if isinstance(cond, str) and any(r.search(cond) for r in anywhere):
            found[(job_name, ("job",))] = cond
        ids = set()
        for n, step in enumerate(job.get("steps") if isinstance(job.get("steps"), list) else [], 1):
            if not isinstance(step, dict):
                continue
            cond = step.get("if")
            held[(job_name, step_selector(step, n))] = cond
            index[(job_name, step_selector(step, n))] = n
            if step.get("id") in checked:
                continue  # a checked version step's if: is version_step's to hold
            text = cond if isinstance(cond, str) else ""
            if not (any(r.search(text) for r in anywhere + own)
                    or any(re.search(rf"\bsteps\.{re.escape(i)}\.", text) for i in ids)):
                continue
            if isinstance(step.get("id"), str):
                ids.add(step["id"])
            found[(job_name, step_selector(step, n))] = text
    listed = {(job, reader_selector(reader)): reader.if_ for (workflow, job), readers in plan.DECISION_READERS.items()
              if workflow == path for reader in readers}

    why = ("it reads a checked version step's decision, and an if: that skips it throws the decision away as "
           "a job output `skip: \"true\"` does")
    for (job_name, selector), want in sorted(listed.items()):
        name = described(selector)
        if (job_name, selector) not in held:
            problem(f"in {path}'s job {job_name}, {name}, which {PLAN}'s DECISION_READERS names with the if: `{want}`, "
                    f"is not there: {why}; a step that moved or was renamed needs its entry changed too", path)
        elif held[(job_name, selector)] != want:
            problem(f"{name} of {job_name} has the if: {rendered(held[(job_name, selector)])}, where {PLAN}'s "
                    f"DECISION_READERS names `{want}` for it: {why}", path)
    for (job_name, selector), have in sorted(found.items()):
        if (job_name, selector) not in listed:
            problem(f"{described(selector)} of {job_name} has the if: `{have}`, which reads a checked version step's "
                    f"decision, and {PLAN}'s DECISION_READERS names no such reader: a new step or job that reads the "
                    f"decision is an entry there, so that no edit of its if: can throw the decision away unseen", path)
    # The order the listed readers run in: each reads the outcome of one before it, so a reader moved
    # above the step it reads finds no outcome and skips, and every reader after it with it.
    for (workflow, job_name), readers in sorted(plan.DECISION_READERS.items()):
        if workflow != path:
            continue
        placed = [(index[(job_name, reader_selector(r))], reader_selector(r)) for r in readers
                  if r.position != 0 and (job_name, reader_selector(r)) in index]
        for (before, first), (after, second) in itertools.pairwise(placed):
            if after <= before:
                problem(f"in {path}'s job {job_name}, {described(second)} is step {after}, before {described(first)}, "
                        f"step {before}, where {PLAN}'s DECISION_READERS lists it after: a reader that runs before "
                        f"the step whose outcome it reads finds none and skips, and the chain after it with it", path)
                break


def version_steps(path, doc):
    """Rule 3 for the workflow `path`: its env: is a literal mapping of WORKFLOW_ENV_KEYS' variables
    alone, its defaults: none or bash, each of its VERSION_STEPS is held by version_step, and
    each if: that reads their decisions by decision_readers."""
    env = doc.get("env") if isinstance(doc, dict) else None
    if env is not None and not isinstance(env, dict):
        problem(f"{path}'s workflow env: is {rendered(env)}, an expression, not a literal mapping, so no one can "
                f"read what it sets for its checked version steps", path)
    for key in sorted(set(env) - set(plan.WORKFLOW_ENV_KEYS.get(path, ()))) if isinstance(env, dict) else ():
        problem(f"{path}'s workflow env: sets {key}, which {PLAN}'s WORKFLOW_ENV_KEYS does not list for it: every "
                f"workflow variable reaches its checked version steps, and one that a shell, the dynamic loader, git "
                f"or gh reads (BASH_ENV, PATH, LD_PRELOAD, GIT_DIR, GH_REPO, …) changes what they hand "
                f"release-push.sh or what it reads; list it there only if it is none of those", path)
    defaults_problem(f"{path}'s workflow", doc.get("defaults") if isinstance(doc, dict) else None,
                     "its checked version steps", path)
    for spec in plan.VERSION_STEPS:
        if spec.workflow == path:
            version_step(doc, spec)
    decision_readers(path, doc)


def legion(go):
    """The legion line: rules 1 to 3, and 5 and 6 for its listings."""
    text = read(RELEASE)
    lines = text.split("\n")
    doc = load(RELEASE, text)
    plain, excludes = pathspecs(RELEASE, doc, HAND)
    listings = plan.legion_listings(targets(TARGETS, "legion", pairs=True))
    found = named(go, listings)
    refuse_excluded(RELEASE, HAND, excludes, found)
    report_and_stop_on_problems()

    inputs = sorted(path for path in found if not any(covers(spec, path) for spec in plain))
    body = [f"  {BLOCK}: >-", *(f"    {path}" for path in inputs)] if inputs else [f'  {BLOCK}: ""']
    want = [*HEAD, *body, END]
    begins = [i for i, line in enumerate(lines) if line.startswith(BEGIN)]
    if len(begins) != 1:
        fatal(f"{RELEASE} must hold one block from `{BEGIN.strip()}` to `{END.strip()}`, which {SELF} write "
              f"fills; it holds {len(begins)}", RELEASE)
    begin = begins[0]
    end = next((i for i in range(begin + 1, len(lines)) if lines[i] == END), None)
    if end is None:
        fatal(f"{RELEASE}'s block from line {begin + 1} has no `{END.strip()}` line", RELEASE)
    have = lines[begin:end + 1]
    if have != want:
        if MODE == "write":
            lines[begin:end + 1] = want
            text = "\n".join(lines)
            Path(RELEASE).write_text(text, encoding="utf-8")
            doc = load(RELEASE, text)
            print(f"wrote {RELEASE}'s {BLOCK}: {len(inputs)} paths")
        else:
            # The block's paths are its lines indented as the folded value's, comments aside.
            held = {line.strip() for line in have if line.startswith("    ") and not line.lstrip().startswith("#")}
            lacks = [path for path in inputs if path not in held]
            extra = sorted(held - set(inputs))
            parts = ([f"it lacks {', '.join(lacks)}, which go names"] if lacks else []) + (
                [f"it names {', '.join(extra)}, which go does not"] if extra else [])
            problem(f"{BLOCK} is not what go decides the legion binary from beyond {HAND}'s paths: "
                    f"{'; '.join(parts) or 'its text is not the block write writes'}; run `{SELF} write`",
                    RELEASE, line=begin + 1)
    elif MODE == "write":
        print(f"{RELEASE}'s {BLOCK} already holds what go names: {len(inputs)} paths")

    if have == want or MODE == "write":
        value = env_of(RELEASE, doc).get(BLOCK)
        if not isinstance(value, str) or value.split() != inputs:
            problem(f"the block from line {begin + 1} is not the {BLOCK} of {RELEASE}'s workflow env:, "
                    f"which legion_build's version step reads", RELEASE, line=begin + 1)

    version_steps(RELEASE, doc)
    packages = sum(path.endswith("/") for path in inputs)
    return (f"{RELEASE}'s {BLOCK} is what go decides the legion binary from beyond {HAND}'s paths: "
            f"{packages} package directories and {len(inputs) - packages} module files, over "
            f"{', '.join(listing.label.removeprefix('./cmd/legion for ') for listing in listings)}")


def legion_envoy(go):
    """The legion-envoy line: rules 3 to 6."""
    doc = load(LISTENER, read(LISTENER))
    plain, excludes = pathspecs(LISTENER, doc, ENVOY_ARGS)
    version_steps(LISTENER, doc)
    listings = plan.legion_envoy_listings(targets(TARGETS, "envoy", pairs=False),
                                          targets(CLIENT_TARGETS, "agent-secrets-client", pairs=True))
    found = named(go, listings)
    refuse_excluded(LISTENER, ENVOY_ARGS, excludes, found)
    for path, label in sorted(found.items()):
        if not any(covers(dropped, path) for _, dropped in excludes) and not any(covers(spec, path) for spec in plain):
            problem(f"{ENVOY_ARGS} names no path that covers {path}, which go names for {label}, so a "
                    f"change to it releases nothing; add it after `--`", LISTENER)
    packages = sum(path.endswith("/") for path in found)
    return (f"{LISTENER}'s {ENVOY_ARGS} covers what go decides the archives from: {packages} package "
            f"directories and {len(found) - packages} module files, over {len(listings)} listings")


modcache = tempfile.mkdtemp(prefix="check-legion-version-inputs-")
try:
    verdicts = [legion(Go(DAEMON, modcache)), legion_envoy(Go(ENVOY, modcache))]
finally:
    shutil.rmtree(modcache, True)
report_and_stop_on_problems()
print("\n".join(verdicts))
PY
